    local ok, err = pcall(__module_z1_lfo, env)
    if not ok then print("Z1 merged: error loading z1-lfo: " .. tostring(err)) end
    if rawget(_G, "evalZ1Wave") == nil then _G.evalZ1Wave = env.evalZ1Wave end
    if rawget(_G, "updateLfoModControls") == nil then _G.updateLfoModControls = env.updateLfoModControls end
    __export(env, "lf_onStaticLfo", "onStaticLfo")
